package dev.openallay.runtime.forge1122;
public final class CapabilityPhaseTest {
    static java.util.Map<String,String> methods(byte[] bytes,boolean normalize) {
        org.objectweb.asm.tree.ClassNode node=new org.objectweb.asm.tree.ClassNode();new org.objectweb.asm.ClassReader(bytes).accept(node,0);
        java.util.Map<String,String> facts=new java.util.LinkedHashMap<String,String>();
        for(Object object:node.methods) {
            org.objectweb.asm.tree.MethodNode method=(org.objectweb.asm.tree.MethodNode)object;
            if(normalize)for(org.objectweb.asm.tree.AbstractInsnNode i=method.instructions.getFirst();i!=null;i=i.getNext()) {
                if(!(i instanceof org.objectweb.asm.tree.MethodInsnNode))continue;org.objectweb.asm.tree.MethodInsnNode m=(org.objectweb.asm.tree.MethodInsnNode)i;
                if("net/minecraftforge/common/util/EnumHelper".equals(m.owner)&&"setFailsafeFieldValue".equals(m.name)){
                    m.owner=CapabilityBridge.HELPER;m.name="setField";}
            }
            org.objectweb.asm.util.Textifier text=new org.objectweb.asm.util.Textifier();method.accept(new org.objectweb.asm.util.TraceMethodVisitor(text));facts.put(method.name+method.desc,text.text.toString());
        }
        return facts;
    }
    public static void main(String[] args)throws Exception {
        byte[] phase=java.util.Base64.getDecoder().decode("");
        byte[] patched=CapabilityBridge.patch(phase,true);
        if(!methods(phase,true).equals(methods(patched,false)))throw new AssertionError("Instructions outside exact setter call changed");
        try{CapabilityBridge.patch(phase);throw new AssertionError("Rawphase guard acceptedpostForgebytes");}catch(IllegalStateException expected){}
        phase[phase.length-1]^=1;
        try{CapabilityBridge.patch(phase,true);throw new AssertionError("Modifiedphase accepted");}catch(IllegalStateException expected){}
        System.out.println("PASS real37533733535 exactpostForgephase; allother instructions unchanged; rawphase distinct; modifiedphase reject");
    }
}
